#include "dxbc_converter.hpp"
#include <malloc/malloc.h>
#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <vector>
#include <cstdlib>
static void require(bool x){if(!x)std::abort();}
static std::vector<char> read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);return {(std::istreambuf_iterator<char>(f)),{}};}
static void write(const std::filesystem::path&p,const void*b,size_t n){std::ofstream f(p,std::ios::binary);f.write((const char*)b,n);require(bool(f));}
static sm50_shader_t init(const std::vector<char>&bc,MTL_SHADER_REFLECTION*r=nullptr){sm50_shader_t h=nullptr;sm50_error_t e=nullptr;int status=SM50Initialize(bc.data(),bc.size(),&h,r,&e);if(e){fprintf(stderr,"%s\n",SM50GetErrorMessageString(e).c_str());SM50FreeError(e);}require(!status&&h);return h;}
static void emit(sm50_shader_t a,sm50_shader_t b,int kind,const std::filesystem::path&p){sm50_bitcode_t bit=nullptr;sm50_error_t e=nullptr;int status=0;switch(kind){case -1:status=SM50Compile(a,nullptr,"compact_equivalence",&bit,&e);break;case 0:status=SM50CompileTessellationPipelineHull(a,b,nullptr,"compact_equivalence",&bit,&e);break;case 1:status=SM50CompileTessellationPipelineDomain(a,b,nullptr,"compact_equivalence",&bit,&e);break;case 2:status=SM50CompileGeometryPipelineVertex(a,b,nullptr,"compact_equivalence",&bit,&e);break;case 3:status=SM50CompileGeometryPipelineGeometry(a,b,nullptr,"compact_equivalence",&bit,&e);break;}if(e){fprintf(stderr,"%s\n",SM50GetErrorMessageString(e).c_str());SM50FreeError(e);}require(!status&&bit);SM50_COMPILED_BITCODE d{};SM50GetCompiledBitcode(bit,&d);write(p,d.Data,d.Size);SM50DestroyBitcode(bit);}
int main(int argc,char**argv){require(argc==3);std::filesystem::path input=argv[1],out=argv[2];std::filesystem::create_directory(out);std::vector<std::filesystem::path>files;for(auto&e:std::filesystem::directory_iterator(input))if(e.path().extension()==".dxbc")files.push_back(e.path());std::sort(files.begin(),files.end());require(files.size()==13);for(auto&p:files){auto bc=read(p);MTL_SHADER_REFLECTION r{};auto h=init(bc,&r);auto*internal=(dxmt::dxbc::SM50ShaderInternal*)h;size_t backing=0,capacity=0,used=0;for(auto&b:internal->bbs){struct State{void*data;size_t capacity,size;}s;static_assert(sizeof(s)==sizeof(b->instructions));memcpy(&s,&b->instructions,sizeof(s));if(s.data)backing+=malloc_size(s.data);capacity+=s.capacity;used+=s.size;}auto name=p.filename().string();write(out/(name+".reflection"),&r,sizeof(r));std::vector<MTL_SM50_SHADER_ARGUMENT>a(r.NumConstantBuffers+r.NumArguments);SM50GetArgumentsInfo(h,a.data(),a.empty()?nullptr:a.data()+r.NumConstantBuffers);write(out/(name+".arguments"),a.data(),a.size()*sizeof(a[0]));if(internal->shader_type==0||internal->shader_type==1||internal->shader_type==5){emit(h,nullptr,-1,out/(name+".bitcode"));emit(h,nullptr,-1,out/(name+".repeat"));}SM50Destroy(h);std::vector<long long>times;for(int i=0;i<205;i++){auto t=std::chrono::steady_clock::now();auto x=init(bc);auto elapsed=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-t).count();SM50Destroy(x);if(i>=4)times.push_back(elapsed);}std::sort(times.begin(),times.end());printf("{\"file\":\"%s\",\"backing\":%zu,\"capacity\":%zu,\"used\":%zu,\"p50_ns\":%lld,\"p95_ns\":%lld}\n",name.c_str(),backing,capacity,used,times[100],times[190]);}
const char*names[]={"7208-simple_vs.dxbc","7257-simple_hs.dxbc","7277-simple_ds.dxbc","7317-simple_gs.dxbc"};for(int k=0;k<4;k++){auto a=read(input/names[k==1?1:0]),b=read(input/names[k==0?1:k==1?2:3]);auto x=init(a),y=init(b);emit(x,y,k,out/("pair"+std::to_string(k)));emit(x,y,k,out/("pair"+std::to_string(k)+".repeat"));SM50Destroy(x);SM50Destroy(y);}return 0;}
